import * as http from "node:http";
import { defineTool, getMarkdownTheme, type ExtensionAPI, type ExtensionContext } from "@earendil-works/pi-coding-agent";
import { Type } from "typebox";
import { formatContextWindowReport, requireKnownContextUsage } from "./context-window.ts";
import { renderTeamMessage } from "./render.ts";

type JsonRecord = Record<string, unknown>;

const teamMessageType = "pi-simple-team";
const defaultInterruptWaitTimeoutMilliseconds = 25_000;
const lifecycleCallbackRetryAttempts = 3;

export interface ChildRuntimeConfig {
	callbackUrl: string;
	callbackToken: string;
	teamId?: string;
	teamName: string;
	teammateName: string;
	participants: string[];
	canOverseeOwnTeams: boolean;
	interruptWaitTimeoutMilliseconds?: number;
}

function requiredEnvironmentVariable(name: string): string {
	const value = process.env[name];
	if (!value) throw new Error(`Missing ${name}`);
	return value;
}

function readParticipants(): string[] {
	const value = requiredEnvironmentVariable("PI_SIMPLE_TEAM_PARTICIPANTS");
	const participants = JSON.parse(value) as unknown;
	if (!Array.isArray(participants) || participants.some((participant) => typeof participant !== "string")) {
		throw new Error("PI_SIMPLE_TEAM_PARTICIPANTS must be a JSON string array");
	}
	return participants;
}

function readRequiredChildRuntimeConfig(): ChildRuntimeConfig {
	const teamId = requiredEnvironmentVariable("PI_SIMPLE_TEAM_TEAM");
	return {
		callbackUrl: requiredEnvironmentVariable("PI_SIMPLE_TEAM_CALLBACK_URL"),
		callbackToken: requiredEnvironmentVariable("PI_SIMPLE_TEAM_CALLBACK_TOKEN"),
		teamId,
		teamName: process.env.PI_SIMPLE_TEAM_TEAM_NAME ?? teamId,
		teammateName: requiredEnvironmentVariable("PI_SIMPLE_TEAM_MEMBER"),
		participants: readParticipants(),
		canOverseeOwnTeams: process.env.PI_SIMPLE_TEAM_CAN_OVERSEE_OWN_TEAMS === "1",
	};
}

export function readChildRuntimeConfig(): ChildRuntimeConfig | undefined {
	if (process.env.PI_SIMPLE_TEAM_CHILD !== "1") return undefined;
	return readRequiredChildRuntimeConfig();
}

export async function callParent(config: ChildRuntimeConfig, tool: string, args: JsonRecord, signal?: AbortSignal): Promise<JsonRecord> {
	const response = await fetch(config.callbackUrl, {
		method: "POST",
		headers: { "content-type": "application/json" },
		body: JSON.stringify({
			token: config.callbackToken,
			team: config.teamId ?? config.teamName,
			from: config.teammateName,
			tool,
			args,
		}),
		signal,
	});

	if (!response.ok) {
		throw new Error(`team runtime rejected ${tool}: ${response.status} ${await response.text()}`);
	}

	return (await response.json()) as JsonRecord;
}

function toolResult(payload: JsonRecord): { content: [{ type: "text"; text: string }]; details: JsonRecord } {
	return {
		content: [{ type: "text" as const, text: JSON.stringify(payload, null, 2) }],
		details: payload,
	};
}

function writeJson(response: http.ServerResponse, statusCode: number, payload: JsonRecord): void {
	const body = JSON.stringify(payload);
	response.writeHead(statusCode, {
		"content-type": "application/json",
		"content-length": Buffer.byteLength(body),
	});
	response.end(body);
}

async function readJsonBody(request: http.IncomingMessage): Promise<JsonRecord> {
	const chunks: Buffer[] = [];
	for await (const chunk of request) chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
	return JSON.parse(Buffer.concat(chunks).toString("utf8")) as JsonRecord;
}

interface ChildDelivery {
	team: string;
	from: string;
	to: string;
	sentAt: string;
	message: string;
	formattedMessage: string;
	interrupt: boolean;
}

/** The one live runtime every child gets: a delivery server, parent registration, and lifecycle callbacks. */
function startChildRuntime(pi: ExtensionAPI, config: ChildRuntimeConfig): void {
	let server: http.Server | undefined;
	let activeContext: ExtensionContext | undefined;
	let idle = true;
	let idleWaiters: Array<() => void> = [];
	let lifecycleQueue: Promise<void> = Promise.resolve();
	let lifecycleError: Error | undefined;

	const notifyParent = (event: JsonRecord): Promise<void> => {
		lifecycleQueue = lifecycleQueue.then(async () => {
			if (lifecycleError) return;
			for (let attempt = 1; attempt <= lifecycleCallbackRetryAttempts; attempt += 1) {
				try {
					await callParent(config, "event", { event });
					return;
				} catch (error) {
					if (attempt === lifecycleCallbackRetryAttempts) lifecycleError = error instanceof Error ? error : new Error(String(error));
				}
			}
		});
		return lifecycleQueue;
	};

	const waitForIdle = async (): Promise<void> => {
		if (idle) return;
		await new Promise<void>((resolve, reject) => {
			let resolveIdle: () => void;
			const timeout = setTimeout(() => {
				idleWaiters = idleWaiters.filter((waiter) => waiter !== resolveIdle);
				reject(new Error("Timed out waiting for the child to settle after interrupt"));
			}, config.interruptWaitTimeoutMilliseconds ?? defaultInterruptWaitTimeoutMilliseconds);
			resolveIdle = (): void => {
				clearTimeout(timeout);
				resolve();
			};
			idleWaiters.push(resolveIdle);
		});
	};

	const markIdle = (): void => {
		idle = true;
		activeContext = undefined;
		const waiters = idleWaiters;
		idleWaiters = [];
		for (const resolve of waiters) resolve();
	};

	pi.on("agent_start", (event, context) => {
		idle = false;
		activeContext = context;
		notifyParent({ type: "agent_start" });
	});
	pi.on("agent_end", (event) => {
		notifyParent({ type: "agent_end", messages: event.messages });
	});
	pi.on("agent_settled", () => {
		notifyParent({ type: "agent_settled" });
		markIdle();
	});
	pi.on("tool_execution_start", (event) => {
		notifyParent({ type: "tool_execution_start", toolCallId: event.toolCallId, toolName: event.toolName, args: event.args });
	});
	pi.on("tool_execution_end", (event) => {
		notifyParent({ type: "tool_execution_end", toolCallId: event.toolCallId, toolName: event.toolName, isError: event.isError, result: event.result });
	});
	pi.on("session_start", async (_event, context) => {
		server = http.createServer((request, response) => {
			void (async () => {
				try {
					const body = await readJsonBody(request);
					if (body.token !== config.callbackToken) {
						writeJson(response, 403, { error: "invalid token" });
						return;
					}

					if (body.tool === "report_context_window") {
						writeJson(response, 200, { contextUsage: requireKnownContextUsage(context.getContextUsage()) });
						return;
					}

					if (body.tool !== "deliver") {
						writeJson(response, 400, { error: `unknown tool: ${String(body.tool)}` });
						return;
					}

					const delivery = body.args as unknown as ChildDelivery;
					if (lifecycleError) throw new Error(`Lifecycle callback failed: ${lifecycleError.message}`);
					if (delivery.interrupt && activeContext) {
						activeContext.abort();
						await waitForIdle();
					}

					pi.sendMessage(
						{
							customType: teamMessageType,
							content: delivery.formattedMessage,
							display: true,
							details: {
								team: delivery.team,
								from: delivery.from,
								to: delivery.to,
								sentAt: delivery.sentAt,
								message: delivery.message,
							},
						},
						{ deliverAs: "steer", triggerTurn: true },
					);
					writeJson(response, 200, { accepted: true, team: config.teamName, from: delivery.from, to: delivery.to, interrupt: delivery.interrupt });
				} catch (error) {
					writeJson(response, 500, { error: error instanceof Error ? error.message : String(error) });
				}
			})();
		});

		await new Promise<void>((resolve, reject) => {
			server!.once("error", reject);
			server!.listen(0, "127.0.0.1", () => resolve());
		});
		const address = server.address();
		if (!address || typeof address === "string") throw new Error("Child delivery server did not get a port");

		try {
			await callParent(config, "register", {
				url: `http://127.0.0.1:${address.port}/deliver`,
				sessionId: context.sessionManager.getSessionId(),
				sessionFile: context.sessionManager.getSessionFile(),
			});
		} catch (error) {
			context.shutdown();
			throw error;
		}
	});

	pi.on("session_shutdown", async (event) => {
		markIdle();
		await notifyParent({ type: "session_shutdown", reason: event.reason });
		await new Promise<void>((resolve, reject) => {
			if (!server) {
				resolve();
				return;
			}
			server.close((error) => (error ? reject(error) : resolve()));
		});
	});
}

export function registerChildTools(pi: ExtensionAPI, config: ChildRuntimeConfig): void {
	pi.registerMessageRenderer(teamMessageType, (message, _options, theme) => renderTeamMessage(message, theme, getMarkdownTheme(), config.participants));
	const startupRosterInstruction = `Participants: main, ${config.participants.join(", ")}.`;
	pi.on("before_agent_start", async (event, context) => {
		const teamContext = await callParent(config, "team_context", {}, context.signal);
		const rawParticipants: unknown = teamContext.participants;
		if (!Array.isArray(rawParticipants) || rawParticipants.some((participant: unknown) => typeof participant !== "string")) {
			throw new Error("team runtime returned an invalid participant list");
		}
		const participants = rawParticipants as string[];
		if (!event.systemPrompt.includes(startupRosterInstruction)) {
			throw new Error("team runtime could not find its startup roster instruction");
		}
		config.participants.splice(0, config.participants.length, ...participants);
		return {
			systemPrompt: event.systemPrompt.replace(
				startupRosterInstruction,
				`Participants: main, ${participants.join(", ")}.`,
			),
		};
	});
	startChildRuntime(pi, config);

	pi.registerTool(
		defineTool({
			name: "report_context_window",
			label: "Report Context Window",
			description: "Report your current context-window use.",
			parameters: Type.Object({}),
			async execute(_toolCallId, _params, _signal, _onUpdate, context) {
				const text = formatContextWindowReport("You have", requireKnownContextUsage(context.getContextUsage()));
				return { content: [{ type: "text" as const, text }], details: {} };
			},
		}),
	);

	pi.registerTool(
		defineTool({
			name: "teamsend",
			label: "Team Send",
			description: "Send a message to teammate(s) (not main). To message the main agent, use teammain. Returns once the runtime accepts the send request, not after recipients reply.",
			parameters: Type.Object({
				to: Type.Array(Type.String(), { description: "Recipient teammate names" }),
				message: Type.String({ description: "Message to send" }),
				interrupt: Type.Optional(Type.Boolean({ description: "Abort busy recipients before delivering this message." })),
			}),
			async execute(_toolCallId, params, signal) {
				return toolResult(await callParent(config, "teamsend", params, signal));
			},
		}),
	);

	// TODO: should be renamed `sendmain` across the project.
	pi.registerTool(
		defineTool({
			name: "teammain",
			label: "Team Main",
			description: "Send a message to the main agent.",
			parameters: Type.Object({
				message: Type.String({ description: "Message to send to the main agent" }),
			}),
			async execute(_toolCallId, params, signal) {
				return toolResult(await callParent(config, "teammain", params, signal));
			},
		}),
	);

	pi.registerTool(
		defineTool({
			name: "teamstatus",
			label: "Team Status",
			description: "Set your public status and read everyone's public status.",
		// TODO: If this typing system supports it, I want gerund and phrase optionality to be a XOR
			parameters: Type.Object({
				gerund: Type.Optional(Type.String({ description: "One-word gerund status." })),
				phrase: Type.Optional(Type.String({ description: "Short status phrase. Verb-oriented." })),
			}),
			async execute(_toolCallId, params, signal) {
				return toolResult(await callParent(config, "teamstatus", params, signal));
			},
		}),
	);
}

export default function (pi: ExtensionAPI) {
	registerChildTools(pi, readRequiredChildRuntimeConfig());
}
import type { ExtensionCommandContext } from "@earendil-works/pi-coding-agent";
import { getKeybindings, SelectList, sliceByColumn, truncateToWidth, visibleWidth, type Component, type SelectItem, type TUI } from "@earendil-works/pi-tui";

import {
	actorHueToken,
	relativeTimeText,
	statusWordToken,
	teamLineText,
	teamLogLines,
	teamMessageLines,
	type TeamMessageDetails,
	type TeamStatusView,
	type ThemeLike,
} from "./render.ts";
import { glyphs } from "./render-support/glyphs.ts";
import type { TeamLogEntry, TeamLogKind } from "./teamlog.ts";

export interface TeamSnapshot {
	name: string;
	created: string;
	showOnHerdrPanes: boolean;
	roster: string[];
	statuses: Record<string, TeamStatusView>;
	log: TeamLogEntry[];
}

export type TeamSnapshotSource = () => readonly TeamSnapshot[];

const RECENT_STATUS_LIMIT = 5;

type ZoomableWidget = "messages" | "log";

interface WidgetView {
	title: string;
	lines: string[];
}
const LIVE_REFRESH_INTERVAL_MILLISECONDS = 500;
const MESSAGE_LOG_KINDS = new Set<TeamLogKind>(["send", "deliver", "ack", "main_message"]);

const overlayOptions = {
	overlay: true,
	overlayOptions: { anchor: "center", width: "90%", maxHeight: "90%" },
} as const;

function teamMessage(entry: TeamLogEntry): TeamMessageDetails | undefined {
	if (entry.kind !== "send" && entry.kind !== "main_message") return undefined;
	const details = entry.details as { from: string; to: string; message: string };
	return {
		team: entry.team,
		from: entry.kind === "main_message" ? entry.teammate! : details.from,
		to: entry.kind === "main_message" ? "main" : details.to,
		sentAt: entry.timestamp,
		message: details.message,
	};
}

/** middleTruncateToWidth("abcdefghij", 7) === "abc…hij" */
function middleTruncateToWidth(text: string, width: number, pad = false): string {
	const targetWidth = Math.max(0, width);
	const textWidth = visibleWidth(text);
	if (textWidth <= targetWidth) return pad ? `${text}${" ".repeat(targetWidth - textWidth)}` : text;
	if (targetWidth === 0) return "";

	const ellipsis = "…";
	const ellipsisWidth = visibleWidth(ellipsis);
	if (ellipsisWidth >= targetWidth) return truncateToWidth(ellipsis, targetWidth, "", pad);

	const retainedWidth = targetWidth - ellipsisWidth;
	const leftWidth = Math.ceil(retainedWidth / 2);
	const rightWidth = Math.floor(retainedWidth / 2);
	const left = sliceByColumn(text, 0, leftWidth, true);
	const right = sliceByColumn(text, textWidth - rightWidth, rightWidth, true);
	const reset = text.includes("\x1b") ? "\x1b[0m" : "";
	const result = `${left}${reset}${ellipsis}${reset}${right}`;
	return pad ? `${result}${" ".repeat(Math.max(0, targetWidth - visibleWidth(result)))}` : result;
}

/** Keeps the most recently updated status first. */
function recentStatuses(statuses: Record<string, TeamStatusView>, limit: number): Array<[string, TeamStatusView]> {
	return Object.entries(statuses)
		.sort(([, left], [, right]) => Date.parse(right.updated) - Date.parse(left.updated))
		.slice(0, limit);
}

function padVisible(text: string, width: number): string {
	return `${text}${" ".repeat(Math.max(0, width - visibleWidth(text)))}`;
}

function statusRows(theme: ThemeLike, statuses: Array<[string, TeamStatusView]>, roster: string[], width: number): string[] {
	const contentWidth = Math.max(0, width - 1);
	const nameWidth = Math.max(0, ...statuses.map(([name]) => visibleWidth(name)));
	const wordWidth = Math.max(0, ...statuses.map(([, status]) => visibleWidth(status.word)));
	const updatedTexts = statuses.map(([, status]) => relativeTimeText(status.updated));
	const timestampWidth = Math.max(0, ...updatedTexts.map((text) => visibleWidth(text)));
	const phraseWidth = Math.max(0, contentWidth - nameWidth - wordWidth - timestampWidth - 6);

	return statuses.map(([name, status], index) => {
		const styledName = theme.fg(actorHueToken(name, roster), name);
		const styledWord = theme.fg(statusWordToken(status.word), status.word);
		const updatedText = updatedTexts[index]!;
		const timestamp = theme.fg("dim", `${" ".repeat(Math.max(0, timestampWidth - visibleWidth(updatedText)))}${updatedText}`);
		const phrase = middleTruncateToWidth(status.phrase, phraseWidth, true);
		return `${padVisible(styledName, nameWidth)}  ${padVisible(styledWord, wordWidth)}  ${phrase}  ${timestamp}`;
	});
}

function limitMessageRows(lines: string[], height: number): string[] {
	if (lines.length <= height) return lines;
	if (height <= 0) return [];
	if (height === 1) return [lines[0]!];
	if (height === 2) return [lines[0]!, `… ${lines.length - 1} message lines omitted …`];

	const body = lines.slice(1);
	const retainedBodyRows = height - 2;
	const leadingRows = Math.ceil(retainedBodyRows / 2);
	const trailingRows = Math.floor(retainedBodyRows / 2);
	return [
		lines[0]!,
		...body.slice(0, leadingRows),
		`… ${body.length - retainedBodyRows} message lines omitted …`,
		...(trailingRows > 0 ? body.slice(-trailingRows) : []),
	];
}

interface MessageLineSelection {
	lines: string[];
	messageCount: number;
}

/** selectNewestMessageLines([["old"], ["new"]], 1).lines[0] === "new" */
function selectNewestMessageLines(groups: string[][], height: number): MessageLineSelection {
	const selectedGroups: string[][] = [];
	let remainingHeight = height;

	for (let index = groups.length - 1; index >= 0; index--) {
		const group = groups[index]!;
		const separatorHeight = selectedGroups.length > 0 ? 1 : 0;
		if (group.length + separatorHeight <= remainingHeight) {
			selectedGroups.unshift(group);
			remainingHeight -= group.length + separatorHeight;
			continue;
		}
		if (selectedGroups.length === 0) selectedGroups.push(limitMessageRows(group, height));
		break;
	}

	return {
		lines: selectedGroups.flatMap((group, index) => [...(index > 0 ? [""] : []), ...group]),
		messageCount: selectedGroups.length,
	};
}

class TeamOverviewOverlay implements Component {
	private selector?: SelectList;
	private selectorTeamNames?: string;
	private selectedTeamName?: string;
	private focusedWidget: ZoomableWidget = "messages";
	private zoomedWidget?: ZoomableWidget;
	private refreshTimer?: ReturnType<typeof setInterval>;
	private closed = false;

	constructor(
		private readonly tui: TUI,
		private readonly theme: ThemeLike,
		private readonly teamSource: TeamSnapshotSource,
		private readonly done: () => void,
	) {
		this.refreshTimer = setInterval(() => this.tui.requestRender(), LIVE_REFRESH_INTERVAL_MILLISECONDS);
		this.refreshTimer.unref?.();
	}

	/** Teams can appear or vanish while the overlay is open, so the selector follows the current snapshot. */
	private refreshSelector(teams: readonly TeamSnapshot[]): void {
		const teamNames = teams.map((team) => team.name).join("\n");
		if (this.selector && this.selectorTeamNames === teamNames) return;
		this.selectorTeamNames = teamNames;
		const items: SelectItem[] = teams.map((team) => ({
			value: team.name,
			label: team.name,
			description: `${team.roster.length} teammate${team.roster.length === 1 ? "" : "s"}`,
		}));
		this.selector = new SelectList(items, this.selectorHeight(teams.length), {
			selectedPrefix: (text) => this.theme.fg("accent", text),
			selectedText: (text) => this.theme.fg("accent", text),
			description: (text) => this.theme.fg("muted", text),
			scrollInfo: (text) => this.theme.fg("dim", text),
			noMatch: (text) => this.theme.fg("warning", text),
		});
		this.selector.onSelect = (item) => {
			this.selectedTeamName = item.value;
			this.tui.requestRender();
		};
		this.selector.onCancel = this.close;
	}

	handleInput(data: string): void {
		if (!this.selectedTeamName && this.selector) {
			this.selector.handleInput(data);
			this.tui.requestRender();
			return;
		}
		const keybindings = getKeybindings();
		if (keybindings.matches(data, "tui.select.cancel")) {
			if (!this.zoomedWidget) {
				this.close();
				return;
			}
			this.zoomedWidget = undefined;
			this.tui.requestRender();
			return;
		}
		if (!this.selectedTeamName || this.zoomedWidget) return;
		if (keybindings.matches(data, "tui.select.up")) this.focusedWidget = "messages";
		else if (keybindings.matches(data, "tui.select.down")) this.focusedWidget = "log";
		else if (keybindings.matches(data, "tui.select.confirm")) this.zoomedWidget = this.focusedWidget;
		else return;
		this.tui.requestRender();
	}

	render(width: number): string[] {
		const height = Math.max(4, Math.floor(this.tui.terminal.rows * 0.9));
		const teams = this.teamSource();
		if (this.selectedTeamName && !teams.some((candidate) => candidate.name === this.selectedTeamName)) {
			this.selectedTeamName = undefined;
			this.zoomedWidget = undefined;
		}
		if (!this.selectedTeamName && teams.length === 1) this.selectedTeamName = teams[0]!.name;
		if (this.selectedTeamName) {
			const team = teams.find((candidate) => candidate.name === this.selectedTeamName)!;
			return this.zoomedWidget ? this.zoom(team, this.zoomedWidget, width, height) : this.dashboard(team, width, height);
		}
		if (teams.length > 1) this.refreshSelector(teams);
		else this.selector = undefined;
		const innerHeight = height - 2;
		return this.frame(this.content(Math.max(1, width - 4), teams).slice(0, innerHeight), width, height);
	}

	invalidate(): void {
		this.selector?.invalidate();
	}

	dispose(): void {
		if (!this.refreshTimer) return;
		clearInterval(this.refreshTimer);
		this.refreshTimer = undefined;
	}

	private readonly close = (): void => {
		if (this.closed) return;
		this.closed = true;
		this.dispose();
		this.done();
	};

	private selectorHeight(teamCount: number): number {
		return Math.max(1, Math.min(teamCount, Math.floor(this.tui.terminal.rows * 0.9) - 8));
	}

	private content(width: number, teams: readonly TeamSnapshot[]): string[] {
		if (teams.length === 0) {
			return [
				this.theme.fg("accent", this.theme.bold("Teams")),
				"",
				"No teams exist.",
				"",
				this.theme.fg("dim", "Esc close"),
			];
		}
		return [
			this.theme.fg("accent", this.theme.bold("Select a team")),
			"",
			...this.selector!.render(width),
			"",
			this.theme.fg("dim", "↑↓ select · Enter open · Esc close"),
		];
	}

	private headerRegion(team: TeamSnapshot, hint: string, contentWidth: number, headerHeight: number, breadcrumb?: string): string[] {
		const transport = team.showOnHerdrPanes ? "Herdr" : "RPC";
		const metadata = [
			`Created ${relativeTimeText(team.created)}`,
			`${team.roster.length} teammate${team.roster.length === 1 ? "" : "s"}`,
			transport,
			hint,
		].join(" · ");
		const title = breadcrumb ? `Team: ${team.name} ${glyphs().chevron} ${breadcrumb}` : `Team: ${team.name}`;
		return this.region(this.theme.fg("accent", this.theme.bold(title)), [this.theme.fg("muted", metadata)], contentWidth, headerHeight);
	}

	private messageWidget(team: TeamSnapshot, contentHeight: number): WidgetView {
		const allMessages = team.log.flatMap((entry) => {
			const message = teamMessage(entry);
			return message ? [message] : [];
		});
		const messageGroups = allMessages.map((message) => teamMessageLines(this.theme, message, team.roster).map(teamLineText));
		const selectedMessages = selectNewestMessageLines(messageGroups, Math.max(0, contentHeight));
		const lines = selectedMessages.lines.length > 0 ? selectedMessages.lines : [this.theme.fg("muted", "No recent messages.")];
		return { title: `Messages · latest ${selectedMessages.messageCount} of ${allMessages.length}`, lines };
	}

	private logWidget(team: TeamSnapshot, contentHeight: number): WidgetView {
		const allLogEntries = team.log.filter((entry) => !MESSAGE_LOG_KINDS.has(entry.kind));
		const renderedLogLines = teamLogLines(this.theme, {
			team: team.name,
			roster: team.roster,
			entries: allLogEntries,
			totalMatched: allLogEntries.length,
			returned: allLogEntries.length,
		}).slice(1);
		const lines = renderedLogLines.slice(-Math.max(0, contentHeight));
		return { title: `Team Log ${team.name} · latest ${lines.length} rows · ${allLogEntries.length} events`, lines };
	}

	private dashboard(team: TeamSnapshot, width: number, height: number): string[] {
		const contentWidth = Math.max(1, width - 2);
		const contentHeight = Math.max(1, height - 2);
		const headerHeight = Math.min(3, Math.max(1, contentHeight - 3));
		const desiredStatusHeight = Math.min(Object.keys(team.statuses).length, RECENT_STATUS_LIMIT) + 2;
		const statusHeight = Math.max(1, Math.min(desiredStatusHeight, contentHeight - headerHeight - 2));
		const feedHeight = contentHeight - headerHeight - statusHeight;
		const messageHeight = Math.max(1, Math.min(feedHeight - 1, Math.round(feedHeight * 0.55)));
		const logHeight = feedHeight - messageHeight;

		const statusContentHeight = Math.max(0, statusHeight - 2);
		const statuses = recentStatuses(team.statuses, Math.min(RECENT_STATUS_LIMIT, statusContentHeight));
		const statusLines = statusRows(this.theme, statuses, team.roster, Math.max(0, contentWidth - 2));

		const messages = this.messageWidget(team, messageHeight - 2);
		const log = this.logWidget(team, logHeight - 2);

		const content = [
			...this.headerRegion(team, "↑↓ widget · Enter zoom · Esc close", contentWidth, headerHeight),
			...this.region(`Team Status ${team.name} · latest ${statuses.length} of ${Object.keys(team.statuses).length}`, statusLines, contentWidth, statusHeight),
			...this.region(messages.title, messages.lines, contentWidth, messageHeight, this.focusedWidget === "messages"),
			...this.region(log.title, log.lines, contentWidth, logHeight, this.focusedWidget === "log"),
		];
		return this.frame(content, width, height);
	}

	private zoom(team: TeamSnapshot, widget: ZoomableWidget, width: number, height: number): string[] {
		const contentWidth = Math.max(1, width - 2);
		const contentHeight = Math.max(1, height - 2);
		const headerHeight = Math.min(3, Math.max(1, contentHeight - 3));
		const widgetHeight = Math.max(1, contentHeight - headerHeight);
		const view = widget === "messages" ? this.messageWidget(team, widgetHeight - 2) : this.logWidget(team, widgetHeight - 2);
		const breadcrumb = widget === "messages" ? "Messages" : "Team Log";
		const content = [
			...this.headerRegion(team, "Esc back to team view", contentWidth, headerHeight, breadcrumb),
			...this.region(view.title, view.lines, contentWidth, widgetHeight, true),
		];
		return this.frame(content, width, height);
	}

	private region(title: string, content: string[], width: number, height: number, focused = false): string[] {
		const frameWidth = Math.max(1, width);
		const border = (text: string): string => this.theme.fg(focused ? "borderAccent" : "border", text);
		if (frameWidth < 3) {
			const top = border(frameWidth === 1 ? "╭" : "╭╮");
			if (height === 1) return [top];
			const row = border("│".repeat(frameWidth));
			return [top, ...Array.from({ length: Math.max(0, height - 2) }, () => row), border(frameWidth === 1 ? "╰" : "╰╯")];
		}

		const innerWidth = frameWidth - 2;
		const labelWidth = Math.max(0, innerWidth - 3);
		const label = middleTruncateToWidth(focused ? `${glyphs().chevron} ${title}` : title, labelWidth);
		const topFill = "─".repeat(Math.max(0, innerWidth - 3 - visibleWidth(label)));
		const top = innerWidth < 3 ? border(`╭${"─".repeat(innerWidth)}╮`) : `${border("╭─ ")}${label}${border(` ${topFill}╮`)}`;
		if (height === 1) return [top];

		const visibleContent = content.slice(0, Math.max(0, height - 2));
		while (visibleContent.length < height - 2) visibleContent.push("");
		const row = (text: string): string => `${border("│")}${middleTruncateToWidth(` ${text}`, innerWidth, true)}${border("│")}`;
		return [top, ...visibleContent.map(row), border(`╰${"─".repeat(innerWidth)}╯`)];
	}

	private frame(content: string[], width: number, height: number): string[] {
		const frameWidth = Math.max(1, width);
		const innerHeight = height - 2;
		const border = (text: string): string => this.theme.fg("border", text);
		if (frameWidth < 3) {
			const row = border("│".repeat(frameWidth));
			return [border(frameWidth === 1 ? "╭" : "╭╮"), ...Array.from({ length: innerHeight }, () => row), border(frameWidth === 1 ? "╰" : "╰╯")];
		}

		const innerWidth = frameWidth - 2;
		const visibleContent = content.slice(0, innerHeight);
		while (visibleContent.length < innerHeight) visibleContent.push("");
		const row = (text: string): string => `${border("│")}${middleTruncateToWidth(text, innerWidth, true)}${border("│")}`;
		return [border(`╭${"─".repeat(innerWidth)}╮`), ...visibleContent.map(row), border(`╰${"─".repeat(innerWidth)}╯`)];
	}
}

export async function openTeamOverview(context: ExtensionCommandContext, teamSource: TeamSnapshotSource): Promise<void> {
	if (context.mode !== "tui") {
		context.ui.notify("/team is available only in interactive mode.", "warning");
		return;
	}
	await context.ui.custom<void>(
		(tui, theme, _keybindings, done) => new TeamOverviewOverlay(tui, theme, teamSource, done),
		overlayOptions,
	);
}
export type TeamLogKind =
	| "spawn"
	| "send"
	| "deliver"
	| "ack"
	| "status"
	| "agent_start"
	| "agent_end"
	| "tool_start"
	| "tool_end"
	| "main_message"
	| "stderr"
	| "exit"
	| "error";

export type TeamLogDirection = "main->teammate" | "teammate->main" | "teammate->teammate" | "runtime";

export interface TeamLogEntry {
	sequence: number;
	timestamp: string;
	epochMilliseconds: number;
	team: string;
	teammate?: string;
	direction?: TeamLogDirection;
	kind: TeamLogKind;
	summary: string;
	details?: Record<string, unknown>;
}

export interface TeamLogState {
	log: TeamLogEntry[];
	nextLogSequence: number;
}

export type TeamLogEntryInput = Omit<TeamLogEntry, "sequence" | "timestamp" | "epochMilliseconds">;

export interface TeamLogFilterParams {
	teammate?: string;
	kind?: string[];
	search?: string;
	since?: string;
}

export interface TeamLogPageParams {
	limit?: number;
	cursor?: string;
}

export interface TeamLogPage {
	entries: TeamLogEntry[];
	totalMatched: number;
	returned: number;
	nextCursor?: string;
	limit: number;
}

export interface TeamLogPageView extends TeamLogPage {
	team: string;
}

const MAX_LOG_ENTRIES = 1000;
const DEFAULT_PREVIEW_LENGTH = 160;
const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;

const dateFormatter = new Intl.DateTimeFormat("en-US", { month: "long", day: "2-digit" });
const timeFormatter = new Intl.DateTimeFormat("en-GB", { hour: "2-digit", minute: "2-digit", second: "2-digit", hour12: false });

export function timeOfDay(epochMilliseconds: number): string {
	return timeFormatter.format(new Date(epochMilliseconds));
}

export function monthDay(epochMilliseconds: number): string {
	return dateFormatter.format(new Date(epochMilliseconds));
}

const MINUTE_MILLISECONDS = 60_000;
const HOUR_MILLISECONDS = 60 * MINUTE_MILLISECONDS;
const DAY_MILLISECONDS = 24 * HOUR_MILLISECONDS;
const WEEK_MILLISECONDS = 7 * DAY_MILLISECONDS;
const MONTH_MILLISECONDS = 30 * DAY_MILLISECONDS;

/** formatElapsed(12 * 60_000) === "12m"; formatElapsed(33 * 3_600_000) === "1d 9h"; formatElapsed(5 * 86_400_000) === "5d" */
function formatElapsed(elapsedMilliseconds: number): string {
	if (elapsedMilliseconds < HOUR_MILLISECONDS) return `${Math.max(1, Math.floor(elapsedMilliseconds / MINUTE_MILLISECONDS))}m`;
	const hours = Math.floor(elapsedMilliseconds / HOUR_MILLISECONDS);
	if (elapsedMilliseconds < 4 * HOUR_MILLISECONDS) {
		const minutes = Math.floor((elapsedMilliseconds % HOUR_MILLISECONDS) / MINUTE_MILLISECONDS);
		return `${hours}h ${String(minutes).padStart(2, "0")}m`;
	}
	if (elapsedMilliseconds < DAY_MILLISECONDS) return `${hours}h`;
	if (elapsedMilliseconds < 2 * DAY_MILLISECONDS) return `1d ${Math.floor((elapsedMilliseconds % DAY_MILLISECONDS) / HOUR_MILLISECONDS)}h`;
	if (elapsedMilliseconds < WEEK_MILLISECONDS) return `${Math.floor(elapsedMilliseconds / DAY_MILLISECONDS)}d`;
	if (elapsedMilliseconds < MONTH_MILLISECONDS) return `${Math.floor(elapsedMilliseconds / WEEK_MILLISECONDS)}w`;
	return `${Math.floor(elapsedMilliseconds / MONTH_MILLISECONDS)}mo`;
}

/**
 * Elapsed-only relative time, one grammar across all tiers.
 * relativeTime(now - 20_000, now) === "just now"; relativeTime(now - 12 * 60_000, now) === "12m ago"; relativeTime(now - 5 * 86_400_000, now) === "5d ago"
 */
export function relativeTime(epochMilliseconds: number, nowMilliseconds: number): string {
	const elapsed = Math.max(0, nowMilliseconds - epochMilliseconds);
	if (elapsed < MINUTE_MILLISECONDS) return "just now";
	return `${formatElapsed(elapsed)} ago`;
}

/**
 * futureTime(now + 20 * 86_400_000, now) === "in 2w"
 */
export function futureTime(epochMilliseconds: number, nowMilliseconds: number): string {
	return `in ${formatElapsed(Math.max(0, epochMilliseconds - nowMilliseconds))}`;
}

function safeStringify(value: unknown): string {
	try {
		return JSON.stringify(value) ?? String(value);
	} catch {
		return String(value);
	}
}

export function preview(value: unknown, maxLength = DEFAULT_PREVIEW_LENGTH): string {
	const text = typeof value === "string" ? value : safeStringify(value);
	const normalized = text.replace(/\s+/g, " ").trim();
	if (normalized.length <= maxLength) return normalized;
	return `${normalized.slice(0, maxLength)} (truncated, ${normalized.length} chars)`;
}

export function appendTeamLog(state: TeamLogState, input: TeamLogEntryInput, now: Date = new Date()): TeamLogEntry {
	const entry: TeamLogEntry = {
		...input,
		sequence: state.nextLogSequence++,
		timestamp: now.toISOString(),
		epochMilliseconds: now.getTime(),
	};
	state.log.push(entry);
	if (state.log.length > MAX_LOG_ENTRIES) state.log.shift();
	return entry;
}

function parseSince(since: string | undefined): number | undefined {
	if (since === undefined) return undefined;
	const threshold = Date.parse(since);
	if (Number.isNaN(threshold)) throw new Error(`Invalid since timestamp: ${since}`);
	return threshold;
}

function matchesSearch(entry: TeamLogEntry, search: string): boolean {
	const needle = search.toLowerCase();
	const haystacks = [entry.summary, entry.teammate ?? "", entry.direction ?? "", entry.kind, entry.details ? safeStringify(entry.details) : ""];
	return haystacks.some((haystack) => haystack.toLowerCase().includes(needle));
}

export function filterTeamLog(entries: TeamLogEntry[], params: TeamLogFilterParams): TeamLogEntry[] {
	const sinceThreshold = parseSince(params.since);
	return entries.filter((entry) => {
		if (params.teammate !== undefined && entry.teammate !== params.teammate) return false;
		if (params.kind !== undefined && !params.kind.includes(entry.kind)) return false;
		if (sinceThreshold !== undefined && entry.epochMilliseconds < sinceThreshold) return false;
		if (params.search !== undefined && !matchesSearch(entry, params.search)) return false;
		return true;
	});
}

function resolveLimit(limit: number | undefined): number {
	if (limit === undefined) return DEFAULT_LIMIT;
	if (!Number.isFinite(limit) || limit < 1) throw new Error(`Invalid limit: ${limit}. Must be at least 1.`);
	return Math.min(Math.floor(limit), MAX_LIMIT);
}

function parseCursor(cursor: string | undefined): number | undefined {
	if (cursor === undefined) return undefined;
	const match = /^before:(\d+)$/.exec(cursor);
	if (!match) throw new Error(`Invalid cursor: ${cursor}`);
	return Number(match[1]);
}

export function pageTeamLog(filteredEntries: TeamLogEntry[], params: TeamLogPageParams): TeamLogPage {
	const limit = resolveLimit(params.limit);
	const beforeSequence = parseCursor(params.cursor);
	const totalMatched = filteredEntries.length;

	const eligible = beforeSequence === undefined ? filteredEntries : filteredEntries.filter((entry) => entry.sequence < beforeSequence);

	const pageEntries = eligible.slice(Math.max(0, eligible.length - limit));
	const hasOlder = eligible.length > pageEntries.length;
	const oldestInPage = pageEntries[0];

	return {
		entries: pageEntries,
		totalMatched,
		returned: pageEntries.length,
		nextCursor: hasOlder && oldestInPage ? `before:${oldestInPage.sequence}` : undefined,
		limit,
	};
}

const COLUMN_WIDTHS = { sequence: 3, time: 8, teammate: 10, kind: 12, direction: 19 } as const;

function column(text: string, width: number): string {
	return text.padEnd(width);
}

function renderRow(entry: TeamLogEntry): string {
	return [
		column(String(entry.sequence).padStart(COLUMN_WIDTHS.sequence, "0"), COLUMN_WIDTHS.sequence),
		column(timeOfDay(entry.epochMilliseconds), COLUMN_WIDTHS.time),
		column(entry.teammate ?? "main", COLUMN_WIDTHS.teammate),
		column(entry.kind, COLUMN_WIDTHS.kind),
		column(entry.direction ?? "", COLUMN_WIDTHS.direction),
		entry.summary,
	].join(" ");
}

export function renderTeamLogPage(view: TeamLogPageView): string {
	const header = `Team ${view.team} — latest ${view.returned} of ${view.totalMatched} matching events`;
	const columnHeader = [
		column("seq", COLUMN_WIDTHS.sequence),
		column("time", COLUMN_WIDTHS.time),
		column("teammate", COLUMN_WIDTHS.teammate),
		column("kind", COLUMN_WIDTHS.kind),
		column("dir", COLUMN_WIDTHS.direction),
		"summary",
	].join(" ");
	const rows = view.entries.map(renderRow);
	const cursorSuffix = view.nextCursor ? ` nextCursor="${view.nextCursor}"` : "";
	const footer = `Showing ${view.returned} of ${view.totalMatched} matching events.${cursorSuffix}`;
	return [header, columnHeader, ...rows, footer].join("\n");
}

/** Child team tools always emit a semantic entry (send/main_message/status), so their tool frames would be pure triplication. */
const TEAM_CHILD_TOOLS = new Set(["teamsend", "teammain", "teamstatus"]);

export function normalizeChildEvent(team: string, teammate: string, event: Record<string, unknown>): TeamLogEntryInput | undefined {
	const type = event.type;

	if (type === "agent_start") {
		return { team, teammate, direction: "runtime", kind: "agent_start", summary: `${teammate} started` };
	}

	if (type === "agent_end") {
		const messages = event.messages;
		const messageCount = Array.isArray(messages) ? messages.length : undefined;
		const summary = messageCount === undefined ? `${teammate} finished` : `${teammate} finished (${messageCount} message${messageCount === 1 ? "" : "s"})`;
		return { team, teammate, direction: "runtime", kind: "agent_end", summary, details: messageCount === undefined ? undefined : { messageCount } };
	}

	if (type === "tool_execution_start") {
		const toolName = String(event.toolName ?? "tool");
		if (TEAM_CHILD_TOOLS.has(toolName)) return undefined;
		return {
			team,
			teammate,
			direction: "runtime",
			kind: "tool_start",
			summary: `${teammate} started ${toolName}: ${preview(event.args)}`,
			details: { toolCallId: event.toolCallId, toolName, args: event.args },
		};
	}

	if (type === "tool_execution_end") {
		const toolName = String(event.toolName ?? "tool");
		if (TEAM_CHILD_TOOLS.has(toolName)) return undefined;
		const isError = Boolean(event.isError);
		return {
			team,
			teammate,
			direction: "runtime",
			kind: "tool_end",
			summary: `${teammate} ${isError ? "failed" : "finished"} ${toolName}: ${preview(event.result)}`,
			details: { toolCallId: event.toolCallId, toolName, isError, result: event.result },
		};
	}

	if (type === "extension_error") {
		return {
			team,
			teammate,
			direction: "runtime",
			kind: "error",
			summary: `${teammate} extension error: ${preview(event.error)}`,
			details: { extensionPath: event.extensionPath, event: event.event, error: event.error },
		};
	}

	return undefined;
}

